import './App.css'
import './Ap'
import 'bootstrap/dist/css/bootstrap.min.css'
import {Container, Badge, ListGroup,ListGroupItem, Form, Button} from 'react-bootstrap'
import { useState,useEffect } from 'react'; // Step 1: import useStart and useEffect
import Axios from 'axios';

function App() {
  const API = "http://localhost:3001/";
  //useState
const [users, setUsers] = useState([]); // Step 2 create useStatect
const [name,setName] = useState("");
const [age,setAge] = useState();
const [email,setEmail] = useState("");
useEffect(()=>{                         // Step 3 create useEffect & copy Axios insed useEffect
Axios.get(`${API}`)
 .then(res=>{
  setUsers(res.data); // Display the setUsers for useState
 });
},[users]);

const createUser=()=>{
  if(name&& age&& email){
 Axios.post(`${API}createUser`, {name, age, email})
  .then(res=>console.log(res.data))
  }
}



  return (
    <Container>
      <Form className='form'>
      <Form.Control type="text" placeholder='Name'onChange={e=>setName(e.target.value)} />
      <Form.Control  type="number" placeholder='Age'onChange={e=>setAge(e.target.value)} />
      <Form.Control type="text" placeholder="Email"onChange={e=>setEmail(e.target.value)} />
      <button onClick={createUser}>Create User</button>
      </Form>
      <div className='result'>
          {users.map(({_id, name, age, email})=>{
      return(
        <ListGroup key={_id}>
          <ListGroupItem variant='dark' className='d-flex justify-content-sm-between'>
            <div className='ms2 me-auto'>
              <div className='fw-bold'>{name}</div>{email}
              </div>

        <div>
          <Badge bg='badge bg-success' pill>{age}</Badge>
          </div>
          </ListGroupItem>
          </ListGroup>





      );
 })}
    </div>

      </Container>

  );
}


export default App;
